UPDATE conversation
SET user_low_last_sync_message_id = CASE
                                        WHEN user_low_id = #{userId}
                                            AND user_low_last_sync_message_id < #{messageId}
                                            THEN #{messageId}
                                        ELSE user_low_last_sync_message_id
                                    END,
    user_high_last_sync_message_id = CASE
                                         WHEN user_high_id = #{userId}
                                             AND user_high_last_sync_message_id < #{messageId}
                                             THEN #{messageId}
                                         ELSE user_high_last_sync_message_id
                                     END
WHERE id = #{conversationId}
  AND (user_low_id = #{userId} OR user_high_id = #{userId})
